import React, { useEffect, useMemo, useState } from "react";

export default function ComplaintHistoryPage() {
  const [complaints, setComplaints] = useState([]);

  useEffect(() => {
    const stored = JSON.parse(localStorage.getItem("complaints")) || [];
    setComplaints(stored);
  }, []);

  const hasComplaints = useMemo(() => complaints.length > 0, [complaints]);

  function deleteComplaint(index) {
    const next = [...complaints];
    next.splice(index, 1);
    setComplaints(next);
    localStorage.setItem("complaints", JSON.stringify(next));
  }

  return (
    <>
      <style>{`
        .complaints {
          width: 60%;
          height: 80vh;
          border-radius: 3%;
          background-color:  #fcf9f9;
          overflow-y: auto;
          padding: 20px;
          box-shadow: 0px 0px 10px rgba(0, 0, 0, 0.1);
        }
        body {
          background-color: #efefef;
          font-family: Arial, sans-serif;
        }
        h1 {
          color: #e55959;
        }
        .complaint-item {
          border-radius: 8px;
          padding: 15px;
          margin-bottom: 10px;
          color: black;
          box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
        }
        .complaint-item:nth-child(odd) {
          background-color: #d0cbcb;
        }
        .complaint-item:nth-child(even) {
          background-color: #e3eaea;
        }
        .delete-btn {
          background-color: #e74c3c;
          border: none;
          color: white;
          padding: 5px 10px;
          border-radius: 5px;
          cursor: pointer;
        }
        .delete-btn:hover {
          background-color: #c0392b;
        }
        .complaint-heading {
          font-weight: bold;
          font-size: 18px;
          color: #e55959;
          margin-bottom: 10px;
        }
      `}</style>

      <center>
        <h1>Complaints</h1>
      </center>
      <center>
        <div className="complaints" id="complaintsContainer">
          {!hasComplaints ? (
            <p>No complaints submitted yet.</p>
          ) : (
            complaints.map((complaint, index) => (
              <div key={index} className="complaint-item">
                <h2 className="complaint-heading">
                  {complaint.complaintType || "General Complaint"}
                </h2>
                <p>
                  <strong>Name:</strong> {complaint.name || "N/A"}
                </p>
                <p>
                  <strong>Roll No:</strong> {complaint.rollNo || "N/A"}
                </p>
                <p>
                  <strong>Email:</strong> {complaint.email || "N/A"}
                </p>
                <p>
                  <strong>Phone Number:</strong> {complaint.phoneNumber || "N/A"}
                </p>
                <p>
                  <strong>Hostel Name:</strong> {complaint.hostelName || "N/A"}
                </p>
                <p>
                  <strong>Room Number:</strong> {complaint.roomNumber || "N/A"}
                </p>
                <p>
                  <strong>Complaint:</strong> {complaint.complaint || "N/A"}
                </p>
                <button className="delete-btn" onClick={() => deleteComplaint(index)}>
                  Delete
                </button>
              </div>
            ))
          )}
        </div>
      </center>
    </>
  );
}
